def solve(payload):
    import math
    resistance, capacitance = payload["resistance_ohm"], payload["capacitance_f"]
    if resistance <= 0 or capacitance <= 0:
        return {"error": "invalid_circuit"}
    if any(t < 0 for t in payload["times_s"]):
        return {"error": "negative_time"}
    source, initial = payload["source_v"], payload["initial_v"]
    tau = resistance * capacitance
    return {"voltages_v": [source + (initial - source) * math.exp(-t / tau) for t in payload["times_s"]]}

